<?php

declare(strict_types=1);

namespace App\Http\Controllers;

use Illuminate\Http\JsonResponse;
use Illuminate\Http\Response;
use Illuminate\Support\Str;
use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;

/**
 * Serves the versioned OpenAPI document (generated by Scribe) and a Swagger UI for it.
 */
final class DocsController extends Controller
{
    public function ui(): Response
    {
        $nonce = Str::random(32);

        return response()
            ->view('docs', ['nonce' => $nonce, 'specUrl' => route('docs.spec')])
            ->header('Content-Security-Policy', implode('; ', [
                "default-src 'none'",
                "script-src 'nonce-{$nonce}' https://cdn.jsdelivr.net",
                "style-src 'self' 'unsafe-inline' https://cdn.jsdelivr.net",
                "img-src 'self' data:",
                "connect-src 'self'",
                "frame-ancestors 'none'",
                "base-uri 'none'",
                "form-action 'self'",
            ]));
    }

    public function spec(): JsonResponse
    {
        $path = config()->string('ticko.openapi_path');

        if (! is_file($path)) {
            throw new NotFoundHttpException;
        }

        /** @var array<string, mixed> $spec */
        $spec = json_decode((string) file_get_contents($path), true, flags: JSON_THROW_ON_ERROR);

        return response()->json($spec);
    }
}
